-- =============================================================================
--  PESOS PROBABILISTICOS DEL MOTOR DE INFERENCIA BAYESIANO
--  Archivo GENERADO por base_datos.py a partir de
--  inferencia/capa_datos/conocimiento_probabilistico.py (no editar a mano).
--  Idempotente: se puede ejecutar sobre una base ya instalada.
-- =============================================================================
USE SistemaExpertoVet;
GO
IF COL_LENGTH('dbo.hipotesis', 'prob_apriori') IS NULL
    ALTER TABLE hipotesis ADD prob_apriori DECIMAL(6,4) NULL;
IF COL_LENGTH('dbo.premisa', 'verosimilitud') IS NULL
    ALTER TABLE premisa ADD verosimilitud DECIMAL(5,4) NULL;
IF OBJECT_ID('dbo.parametro_inferencia', 'U') IS NULL
    CREATE TABLE parametro_inferencia (
        clave       VARCHAR(40)   NOT NULL CONSTRAINT pk_parametro_inferencia PRIMARY KEY,
        valor       DECIMAL(9,4)  NOT NULL,
        descripcion NVARCHAR(200) NOT NULL);
GO
IF OBJECT_ID('dbo.ck_hip_prob_apriori', 'C') IS NULL
    ALTER TABLE hipotesis ADD CONSTRAINT ck_hip_prob_apriori
        CHECK (prob_apriori IS NULL OR (prob_apriori > 0 AND prob_apriori <= 1));
IF OBJECT_ID('dbo.ck_premisa_verosimilitud', 'C') IS NULL
    ALTER TABLE premisa ADD CONSTRAINT ck_premisa_verosimilitud
        CHECK (verosimilitud IS NULL OR (verosimilitud > 0 AND verosimilitud < 1));
GO

-- ---------- Parametros del motor ----------
DELETE FROM parametro_inferencia;
INSERT INTO parametro_inferencia (clave, valor, descripcion) VALUES
  (N'p_fuga', 0.03, N'P(s|H) cuando el sintoma no pertenece al granulo de H'),
  (N'umbral_confianza', 0.9, N'Probabilidad de la hipotesis lider para detener el interrogatorio'),
  (N'min_preguntas', 4, N'Numero minimo de preguntas antes de detenerse'),
  (N'max_preguntas', 15, N'Numero maximo de preguntas'),
  (N'ganancia_minima', 0.005, N'Ganancia de informacion minima (bits) para seguir preguntando'),
  (N'num_hipotesis', 5, N'Numero de hipotesis a reportar');

