-- ---------- Permisos (roles de 04_roles.sql) ----------
IF DATABASE_PRINCIPAL_ID('rol_ingeniero_conocimiento') IS NOT NULL
    GRANT SELECT, INSERT, UPDATE, DELETE ON dbo.parametro_inferencia TO rol_ingeniero_conocimiento;
IF DATABASE_PRINCIPAL_ID('rol_experto') IS NOT NULL
BEGIN
    GRANT SELECT ON dbo.parametro_inferencia TO rol_experto;
    GRANT UPDATE (verosimilitud) ON dbo.premisa TO rol_experto;
    GRANT UPDATE (prob_apriori) ON dbo.hipotesis TO rol_experto;
END
IF DATABASE_PRINCIPAL_ID('rol_usuario_final') IS NOT NULL
    GRANT SELECT ON dbo.parametro_inferencia TO rol_usuario_final;
GO
